38	  const debounceRef = useRef(null);
39	  // runRender is a useCallback with no deps, so reading `format` from the closure would pin
40	  // it to whatever was selected on first render. The ref is what the render call reads.
41	  const formatRef = useRef(CONFIG_FORMAT);
42	
43	  const runRender = useCallback(
44	    (text) => {
45	      render(text, formatRef.current, RENDER_DATA_JSON, RENDER_OPTIONS);
46	    },
47	    [render],
48	  );
49	
50	  useEffect(() => {
51	    ensureLoaded();
52	  }, [ensureLoaded]);
53	
54	  // Resumes the reader's own session (see studioHandoff.js's SESSION_KEY doc comment) and, if a
55	  // segment doc queued one, appends its segment on top - so "Add to Studio" really does add to
56	  // whatever is already here rather than to a pristine starter every time. Runs exactly once, on
57	  // mount: format/configText are intentionally read as their *initial* values (the plain
58	  // STARTER), not the current state, since this effect IS what decides what "current" becomes.
59	  useEffect(() => {
60	    let baseFormat = CONFIG_FORMAT;
61	    let baseText = STARTERS[CONFIG_FORMAT];
62	
63	    const savedRaw = trySessionStorageGet(SESSION_KEY);
64	
65	    if (savedRaw) {
66	      try {
67	        const saved = JSON.parse(savedRaw);
68	
69	        if (saved && typeof saved.text === 'string' && CONFIG_FORMATS.includes(saved.format)) {
70	          baseFormat = saved.format;
71	          baseText = saved.text;
72	        }
73	      } catch {
74	        // Corrupt or foreign sessionStorage value - fall back to the pristine starter.
75	      }
76	    }
77	
78	    const pendingRaw = trySessionStorageGet(APPEND_KEY);
79	
80	    if (pendingRaw) {
81	      // One-shot: consumed here regardless of what happens next, so a later, unrelated studio
82	      // visit never re-applies it.
83	      trySessionStorageRemove(APPEND_KEY);
84	
85	      try {
86	        const payload = JSON.parse(pendingRaw);
87	        const segment = payload && payload.segment;
88	
89	        if (segment && typeof segment === 'object' && !Array.isArray(segment)) {
90	          const parsedBase = parseConfig(baseFormat, baseText);
91	          const blocks = Array.isArray(parsedBase.blocks) ? parsedBase.blocks : [];
92	          let promptBlock = blocks.find((b) => b && b.type === 'prompt' && Array.isArray(b.segments));
93	
94	          if (!promptBlock) {
95	            promptBlock = blocks.find((b) => b && Array.isArray(b.segments));
96	          }
97	
98	          if (!promptBlock) {
99	            promptBlock = { type: 'prompt', alignment: 'left', segments: [] };
100	            blocks.unshift(promptBlock);
101	          }
102	
103	          promptBlock.segments = [...promptBlock.segments, segment];
104	          parsedBase.blocks = blocks;
105	
106	          baseText = stringifyConfig(baseFormat, parsedBase);
107	        }
108	      } catch (err) {
109	        // The spec here is explicit: a config that fails to parse must not be silently
110	        // discarded. Leave baseText exactly as it was (the restored session, or the pristine
111	        // starter) and surface why the segment wasn't added.
112	        setAppendNotice(
113	          `Could not add the segment from the previous page: ${err.message || err}. ` +
114	            'Your current config was left unchanged.',
115	        );
116	      }
117	    }
118	
119	    if (baseFormat !== CONFIG_FORMAT) {
120	      setFormat(baseFormat);
121	      formatRef.current = baseFormat;
122	    }
