const REPO_DIR = join(WEBSITE_DIR, '..');
const SRC_DIR = join(REPO_DIR, 'src');
const BIN = join(SRC_DIR, 'bin', process.platform === 'win32' ? 'oh-my-posh.exe' : 'oh-my-posh');

