}

.subtitle {
  max-width: 52ch;
}

.installBox {
  width: 100%;
  max-width: 560px;
  margin-top: 0.9rem;
  text-align: left;
}

.installNote {
  margin-top: 0.75rem;
  font-size: 0.875rem;
}

.buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem 1.5rem;
  align-items: center;
  justify-content: flex-start;
}

/* No background or border: the rendered SVG draws its own terminal window, so the tinted box the
   screenshot needed to sit in would now be a frame around a frame - the same call the studio and
   the segment previews make. */
.heroPrompt {
  width: 100%;
  max-width: 100%;
}

.svgWrapper {
  display: block;
  width: fit-content;
  max-width: 100%;
}

.svgWrapper :global(svg) {
  display: block;
  max-width: 100%;
  height: auto;
}

.feature {
  margin-bottom: 1.5rem;
}

/* Border, background and radius come from the shared --omp-card-* custom properties in
   src/css/custom.css (radius is 8px there - see that comment for why), which also carries the
   dark-mode override that used to be repeated here. */
